insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-so-124","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mass/volume percent is 100 times the ratio of","options":["mass of solute to volume of solution","volume of solute to mass of solvent","moles of solute to kilograms of solvent","mass of solvent to mass of solute"],"answer_index":0,"explanation":"w/v % = (mass of solute / volume of solution) × 100, with consistent units.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-125","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a very dilute aqueous sample, 1 ppm is nearly the same as","options":["1 mg of solute in one litre of solution","1 g in one litre","1 mol in one litre","1% by mass"],"answer_index":0,"explanation":"1 L of dilute aqueous solution has a mass of about 10³ g, so 1 ppm ≈ 1 mg L⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-126","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molarity of a sealed bottle of solution falls slightly on heating because","options":["moles of solute decrease","the solution volume expands","the solvent mass vanishes","mole fraction becomes undefined"],"answer_index":1,"explanation":"Thermal expansion increases V while n stays fixed, so M = n/V drops.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-127","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Normality of a solution is the number of","options":["gram equivalents of solute in one litre of solution","moles of solute in one kilogram of solvent","mole fraction units per litre","ppm units per kilogram"],"answer_index":0,"explanation":"N = gram equivalents of solute / litres of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-128","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mole fraction is a concentration that is","options":["measured in mol L⁻¹","dimensionless","reported in kg mol⁻¹","identical to ppm"],"answer_index":1,"explanation":"It is a pure number — a ratio of moles to moles.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms"},{"id":"che-so-129","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A student dissolves 10 g of NaOH in 90 g of water. The mass percent of NaOH is","options":["10%","11.1%","9.0%","90%"],"answer_index":0,"explanation":"Mass of solution = 100 g, so w/w % = 10/100 × 100 = 10%.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms"},{"id":"che-so-130","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two moles of ethanol are mixed with three moles of water. Mole fraction of ethanol is","options":["0.40","0.60","0.50","0.67"],"answer_index":0,"explanation":"$x_{\\mathrm{EtOH}} = 2 / (2 + 3) = 0.40$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms"},{"id":"che-so-131","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"4.9 g of H2SO4 (98 g mol⁻¹) made up to 500 mL of solution has molarity","options":["0.10 M","0.20 M","0.05 M","1.0 M"],"answer_index":0,"explanation":"Moles = 4.9/98 = 0.050; volume = 0.50 L, so M = 0.10 mol L⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms"},{"id":"che-so-132","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissolving 6.0 g of urea (60 g mol⁻¹) in 250 g of water produces molality","options":["0.40 m","0.25 m","0.10 m","1.0 m"],"answer_index":0,"explanation":"Moles of urea = 0.10; kilograms of water = 0.250, so m = 0.40 mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms"},{"id":"che-so-133","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 100 ppm aqueous impurity corresponds, in 1.0 kg of solution, to a solute mass of","options":["100 mg","100 g","1.0 g","10 mg"],"answer_index":0,"explanation":"100 × 10⁻⁶ × 1000 g = 0.100 g = 100 mg.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms"},{"id":"che-so-134","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose (180 g mol⁻¹), 9.0 g, sits together with 81 g of water. Mole fraction of glucose is nearest","options":["0.011","0.10","0.050","0.90"],"answer_index":0,"explanation":"n(glucose) = 0.050, n(water) = 4.50, so x = 0.050/4.55 ≈ 0.011.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms"},{"id":"che-so-135","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An aqueous bottle labelled 2.0 M NaCl occupies 250 mL. Moles of NaCl inside are","options":["0.50","2.0","0.25","8.0"],"answer_index":0,"explanation":"n = M V = 2.0 mol L⁻¹ × 0.250 L = 0.50 mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms"},{"id":"che-so-136","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Aqueous HCl is 36.5% (w/w) with density 1.18 g mL⁻¹. Using molar mass 36.5 g mol⁻¹, the molarity is nearest","options":["11.8 M","10.0 M","1.18 M","36.5 M"],"answer_index":0,"explanation":"One litre has mass 1180 g and contains 0.365 × 1180 = 431 g HCl, i.e. 11.8 mol, so M ≈ 11.8.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms"},{"id":"che-so-137","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A flask holds 8.0 g of CH3OH (32 g mol⁻¹) plus 36 g of water. Molality of methanol is nearest","options":["6.9 m","0.25 m","4.0 m","2.2 m"],"answer_index":0,"explanation":"n(CH3OH) = 0.25 mol in 0.036 kg of water, so m = 0.25/0.036 ≈ 6.9 mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms"},{"id":"che-so-138","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mixing 200 mL of 0.60 M H2SO4 with 300 mL of 0.20 M H2SO4, taking volumes as additive, gives a blend of","options":["0.36 M","0.40 M","0.80 M","0.24 M"],"answer_index":0,"explanation":"Moles = 0.12 + 0.06 = 0.18 in 0.50 L, so M = 0.36 mol L⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms"},{"id":"che-so-139","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Henry linked the partial pressure of a dissolved gas to its","options":["mole fraction in the liquid","mass percent alone","molality squared","normal boiling point"],"answer_index":0,"explanation":"One form is $p = K_H x$, with x the mole fraction of the dissolved gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law"},{"id":"che-so-140","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The Henry-law constant $K_H$ is dimensionally a","options":["pressure","volume","molality","entropy"],"answer_index":0,"explanation":"Because $p = K_H x$ and x is dimensionless, $K_H$ has the unit of pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law"},{"id":"che-so-141","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At a fixed temperature, a larger $K_H$ for a gas means that gas is","options":["more soluble","less soluble","exactly as soluble as every other gas","always immiscible"],"answer_index":1,"explanation":"x = p / $K_H$, so a large constant implies a small dissolved mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law"},{"id":"che-so-142","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Soft-drink bottles are packed under extra carbon-dioxide pressure so that","options":["more CO2 remains dissolved until the cap is opened","$K_H$ becomes zero","the drink freezes in the bottle","oxygen is chemically removed"],"answer_index":0,"explanation":"Higher p(CO2) forces a larger x(CO2) in the liquid (Henry’s law).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law"},{"id":"che-so-143","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Deep-sea divers risk decompression sickness because nitrogen","options":["dissolves more at high pressure and bubbles out on a rapid ascent","is insoluble at depth","binds irreversibly to haemoglobin only","forms an azeotrope with blood plasma"],"answer_index":0,"explanation":"High p(N2) loads the blood; a sudden drop in pressure releases bubbles in the tissues.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-so-124","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-125","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-126","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-127","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-128","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-129","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-130","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-131","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-132","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-133","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-134","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-135","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-136","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-137","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-138","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-139","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-140","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-141","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-142","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-143","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
